<?php
require_once __DIR__.'/config.php';require_once __DIR__.'/includes/economy.php';
$id=(int)($_GET['id']??0);$thread=null;foreach(data_load('threads.json') as $item)if((int)($item['id']??0)===$id){$thread=$item;break;}if(!$thread){http_response_code(404);exit('Пост не найден.');}
$replies=data_load('replies_'.$id.'.json');$likes=data_load('likes_thread_'.$id.'.json');$me=current_user();$users=data_load('users.json');$title=($thread['title']??'Пост').' — GREFFRLEND';
$userMap=[];foreach($users as $u)$userMap[(int)($u['id']??0)]=$u;
function avatar_for(array $user): string { return (string)($user['avatar']??'banners/IMG_20260727_215431_065.jpg'); }
function profile_url_for(array $user): string { $h=(string)($user['handle']??$user['username']??'');return $h!==''?SITE_URL.'/'.rawurlencode($h):'profile.php?id='.(int)($user['id']??0); }
function reply_children(array $replies,int $parentId): array{return array_values(array_filter($replies,static fn(array $reply):bool=>(int)($reply['parent_id']??0)===$parentId));}
function premium_style_class(array $item): string { $style=(string)($item['premium_style']??'default');return in_array($style,['glow','glass','accent'],true)?'premium-style-'.$style:''; }
function render_reply(array $reply,array $replies,?array $me,array $userMap,int $threadId,int $level=0): void { $replyId=(int)($reply['id']??0);$replyLikes=data_load('likes_reply_'.$threadId.'_'.$replyId.'.json');$level=min($level,4);$authorId=(int)($reply['author_id']??0);$author=$userMap[$authorId]??['id'=>$authorId,'username'=>$reply['author']??'Пользователь'];$isAuthor=$me&&(int)$authorId===(int)$me['id'];$canEdit=$me&&($isAuthor||is_owner($me));$premium=$authorId>0&&premium($author);$style=$premium?premium_style_class($reply):'';$accent=(string)($author['premium_accent']??'#ff6817');if(!preg_match('/^#[0-9a-fA-F]{6}$/',$accent))$accent='#ff6817';$avatar=avatar_for($author);?>
<article class="card post comment <?=$style?>" id="reply-<?=$replyId?>" style="margin-left:<?=$level*24?>px;--premium-accent:<?=e($accent)?>"><div class="post-meta" style="display:flex;align-items:center;gap:10px"><a href="<?=e(profile_url_for($author))?>" style="display:flex;align-items:center;gap:9px"><img src="<?=e($avatar)?>" alt="" style="width:38px;height:38px;object-fit:cover;border-radius:50%;border:2px solid <?=e($premium?$accent:'#555')?>"><span><b style="<?= $premium?'color:'.e($accent).';':'' ?>"><?=e($author['username']??$reply['author']??'Пользователь')?></b><?php if($premium):?> <span class="premium-badge">⭐</span><?php endif;?></span></a><span><?=e((string)($reply['created_at']??''))?></span><?php if(!empty($reply['updated_at'])):?><span class="edited">изменено</span><?php endif;?></div><div class="post-body"><?=nl2br(e((string)($reply['message']??'')))?></div><?php if(!empty($reply['attachments'])):?><div class="attachments"><?php foreach($reply['attachments'] as $attachment):?><a href="<?=e($attachment)?>" target="_blank" rel="noopener"><img src="<?=e($attachment)?>" alt="Вложение" loading="lazy"></a><?php endforeach;?></div><?php endif;?><div class="reactions"><?php if($me):?><form method="post" action="like.php" class="inline-form"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="type" value="reply"><input type="hidden" name="id" value="<?=$replyId?>"><button class="reaction" type="submit">❤️ <?=count($replyLikes)?></button></form><button class="reaction" type="button" onclick="replyTo(<?=$replyId?>,<?=e(json_encode($author['username']??'Пользователь'))?>)">↩ Ответить</button><?php endif;?><?php if($canEdit):?><button class="reaction" type="button" onclick="toggleEdit('edit-reply-<?=$replyId?>')">✏️ Изменить</button><form method="post" action="content_action.php" class="inline-form"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="type" value="reply"><input type="hidden" name="thread_id" value="<?=$threadId?>"><input type="hidden" name="reply_id" value="<?=$replyId?>"><input type="hidden" name="action" value="delete"><button class="reaction" type="submit">🗑️ Удалить</button></form><?php endif;?></div><?php if($canEdit):?><form id="edit-reply-<?=$replyId?>" class="card form edit-form" style="display:none" method="post" action="content_action.php"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="type" value="reply"><input type="hidden" name="thread_id" value="<?=$threadId?>"><input type="hidden" name="reply_id" value="<?=$replyId?>"><input type="hidden" name="action" value="edit"><label>Редактирование комментария</label><textarea name="message" maxlength="20000" required><?=e((string)($reply['message']??''))?></textarea><button class="btn" type="submit">💾 Сохранить</button> <button class="reaction" type="button" onclick="toggleEdit('edit-reply-<?=$replyId?>')">Отмена</button></form><?php endif;?><?php foreach(reply_children($replies,$replyId) as $child)render_reply($child,$replies,$me,$userMap,$threadId,$level+1);?></article><?php }
$threadAuthorId=(int)($thread['author_id']??0);$author=$userMap[$threadAuthorId]??['id'=>$threadAuthorId,'username'=>$thread['author']??'Пользователь'];$threadPremium=$threadAuthorId>0&&premium($author);$threadStyle=$threadPremium?premium_style_class($thread):'';$accent=(string)($author['premium_accent']??'#ff6817');if(!preg_match('/^#[0-9a-fA-F]{6}$/',$accent))$accent='#ff6817';$canEditThread=$me&&($threadAuthorId===(int)$me['id']||is_owner($me));$canManageThread=$me&&is_owner($me);include __DIR__.'/includes/header.php';
?>
<style>
.thread-author{display:flex;align-items:center;gap:11px}.thread-author-avatar{width:48px;height:48px;object-fit:cover;border-radius:50%;border:2px solid <?=e($threadPremium?$accent:'#555')?>}.thread-author-name{font-weight:900;color:<?=e($threadPremium?$accent:'#fff')?>}.post-meta{flex-wrap:wrap}.comment{overflow:hidden}.premium-style-glow{border-color:var(--premium-accent)!important;box-shadow:0 0 18px color-mix(in srgb,var(--premium-accent) 16%,transparent)}.premium-style-glass{background:linear-gradient(135deg,color-mix(in srgb,var(--premium-accent) 8%,transparent),rgba(255,255,255,.025));border-color:color-mix(in srgb,var(--premium-accent) 45%,#333)}.premium-style-accent{border-left:4px solid var(--premium-accent);border-color:color-mix(in srgb,var(--premium-accent) 45%,#333)}.premium-style-glow .post-body,.premium-style-glass .post-body,.premium-style-accent .post-body{position:relative}.premium-style-glow:before{content:'✦';float:right;color:var(--premium-accent);opacity:.7}.premium-style-glass:before{content:'PREMIUM';float:right;font-size:10px;letter-spacing:1px;color:var(--premium-accent);opacity:.7}.premium-style-accent:before{content:'⭐';float:right;opacity:.75}@media(max-width:700px){.comment{margin-left:0!important}}
</style>
<article class="card post <?=$threadStyle?>" id="post-<?=$id?>" style="--premium-accent:<?=e($accent)?>"><div class="category">ПОСТ</div><h1><?=e($thread['title']??'')?></h1><div class="post-meta"><a class="thread-author" href="<?=e(profile_url_for($author))?>"><img class="thread-author-avatar" src="<?=e(avatar_for($author))?>" alt=""><span><span class="thread-author-name"><?=e($author['username']??$thread['author']??'Пользователь')?></span><?php if($threadPremium):?> <span class="premium-badge">⭐ PREMIUM</span><?php endif;?></span></a><span><?=e((string)($thread['created_at']??''))?></span><?php if(!empty($thread['updated_at'])):?><span class="edited">изменено</span><?php endif;?><?php if(!empty($thread['pinned'])):?><span class="pin">📌 Закреплено</span><?php endif;?></div><div class="post-body"><?=nl2br(e((string)($thread['content']??'')))?></div><?php if(!empty($thread['attachments'])):?><div class="attachments"><?php foreach($thread['attachments'] as $attachment):?><a href="<?=e($attachment)?>" target="_blank" rel="noopener"><img src="<?=e($attachment)?>" alt="Вложение" loading="lazy"></a><?php endforeach;?></div><?php endif;?><div class="reactions"><?php if($me):?><form method="post" action="like.php" class="inline-form"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="type" value="thread"><input type="hidden" name="id" value="<?=$id?>"><button class="reaction" type="submit">❤️ <?=count($likes)?></button></form><?php endif;?><?php if($canEditThread):?><button class="reaction" type="button" onclick="toggleEdit('edit-post')">✏️ Изменить пост</button><?php endif;?><?php if($canManageThread):?><form method="post" action="content_action.php" class="inline-form" onsubmit="return confirm('Удалить этот пост?')"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="type" value="thread"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="action" value="delete"><button class="reaction" type="submit">🗑️ Удалить</button></form><form method="post" action="content_action.php" class="inline-form"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="type" value="thread"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="action" value="<?=!empty($thread['pinned'])?'unpin':'pin'?>"><button class="reaction" type="submit">📌 <?=!empty($thread['pinned'])?'Открепить':'Закрепить'?></button></form><?php endif;?></div><?php if($canEditThread):?><form id="edit-post" class="card form edit-form" style="display:none" method="post" action="content_action.php"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="type" value="thread"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="action" value="edit"><label>Заголовок</label><input name="title" maxlength="120" value="<?=e($thread['title']??'')?>" required><label>Текст поста</label><textarea name="content" maxlength="20000" required><?=e($thread['content']??'')?></textarea><button class="btn" type="submit">💾 Сохранить изменения</button> <button class="reaction" type="button" onclick="toggleEdit('edit-post')">Отмена</button></form><?php endif;?></article>
<h2>Комментарии</h2><?php foreach(reply_children($replies,0) as $reply)render_reply($reply,$replies,$me,$userMap,$id);?>
<?php if($me):?><div class="card form" id="reply-form"><h2>Ответить</h2><div id="replying-to" class="muted"></div><div class="emoji"><?php foreach(['😀','😂','❤️','🔥','👍','👎','🎮','😎','🤔','🎉','💀','🚀','🥳','😢','😡'] as $emoji):?><button type="button" onclick="insertEmoji('<?=e($emoji)?>')"><?=e($emoji)?></button><?php endforeach;?></div><form method="post" action="reply.php" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="thread_id" value="<?=$id?>"><input type="hidden" name="parent_id" id="parent-id" value="0"><textarea id="reply-message" name="message" required maxlength="20000" placeholder="Напишите комментарий..."></textarea><?php if(premium($me)||is_owner($me)):?><label>✨ Оформление комментария</label><select name="premium_style"><option value="default">Обычный</option><option value="glow">Premium Glow</option><option value="glass">Glass</option><option value="accent">Accent</option></select><?php endif;?><label>Фото/GIF — до <?=MAX_ATTACHMENTS?> файлов</label><input type="file" name="attachments[]" accept="image/jpeg,image/png,image/gif,image/webp" multiple><button class="btn" type="submit">Отправить</button></form></div><?php else:?><div class="card">Чтобы отвечать, <a href="login.php">войдите</a> или <a href="register.php">зарегистрируйтесь</a>.</div><?php endif;?>
<script>function insertEmoji(emoji){const field=document.getElementById('reply-message');if(!field)return;const start=field.selectionStart||field.value.length,end=field.selectionEnd||field.value.length;field.value=field.value.slice(0,start)+emoji+field.value.slice(end);field.focus();field.selectionStart=field.selectionEnd=start+emoji.length}function replyTo(id,name){const parent=document.getElementById('parent-id'),label=document.getElementById('replying-to'),form=document.getElementById('reply-form');if(parent)parent.value=id;if(label)label.textContent='Ответ пользователю: '+name+' (Комментарий #'+id+')';if(form)form.scrollIntoView({behavior:'smooth',block:'center'})}function toggleEdit(id){const element=document.getElementById(id);if(!element)return;element.style.display=element.style.display==='none'||!element.style.display?'block':'none'}</script>
